import AppKit
import Foundation

enum Icons {
    // Embedded icon-22.png (white ReadItSoon logo, 1x)
    private static let base64_1x = ""

    // Embedded icon-44.png (white ReadItSoon logo, 2x retina)
    private static let base64_2x = ""

    static var menuBarIcon: NSImage? {
        guard let data1x = Data(base64Encoded: base64_1x),
              let rep1x = NSBitmapImageRep(data: data1x) else { return nil }

        let image = NSImage(size: NSSize(width: 22, height: 22))
        rep1x.size = NSSize(width: 22, height: 22)
        image.addRepresentation(rep1x)

        if let data2x = Data(base64Encoded: base64_2x),
           let rep2x = NSBitmapImageRep(data: data2x) {
            rep2x.size = NSSize(width: 22, height: 22)
            image.addRepresentation(rep2x)
        }

        image.isTemplate = true
        return image
    }

    private static let appIconBase64 = ""

    static var appIcon: NSImage? {
        guard let data = Data(base64Encoded: appIconBase64),
              let image = NSImage(data: data) else { return nil }
        return image
    }
}